const leads = $input.all().map(i => i.json);

const total = leads.length;
const noWebsite = leads.filter(l => l.website_need !== 'HAS_WEBSITE').length;
const hot = leads.filter(l => l.interest === 'HOT' || l.status === 'HOT').length;
const interested = leads.filter(l => l.status === 'INTERESTED' || l.interest === 'INTERESTED').length;
const dnc = leads.filter(l => l.status === 'DO_NOT_CALL').length;

const report = `
📊 DAILY SALES ACQUISITION REPORT
--------------------------------
• Total Leads Discovered: ${total}
• Prospects without Website: ${noWebsite}
• Hot Conversion Leads: ${hot}
• Interested Prospect Leads: ${interested}
• Suppressed DNC Requests: ${dnc}
--------------------------------
Status: Automation Active & Healthy
`;

return [{ json: { report, metrics: { total, noWebsite, hot, interested, dnc } } }];
